import{_ as o,l as i,o as a,c as l,v as t,p as n,x as r,d as p,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"转换成本","description":"","frontmatter":{"title":"转换成本","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/switching-costs.md","filePath":"econ/switching-costs.md","lastUpdated":1789023840000}'),c={name:"econ/switching-costs.md"};function B(h,e,m,A,_,u){const s=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="转换成本" tabindex="-1">转换成本 <a class="header-anchor" href="#转换成本" aria-label="Permalink to &quot;转换成本&quot;">​</a></h1><div class="epigraph"><p>买过之后再换一家要付一笔沉淀；事前为抢客户可以很凶，事后对锁定客户可以加价——竞争从「场内」挪到「入场」。</p><footer>—— 据 Klemperer, Markets with Consumer Switching Costs, Quarterly Journal of Economics, 1987 整理</footer></div><p><a href="/econ/two-sided-platform">上一课</a>（双边市场）。平台用价格结构养两边的交叉网络。本课不重写总价与分摊，也不把多归属再分类一遍。缺口是用户侧的沉淀：学过界面、迁过数据、毁过兼容，换一家有成本 \\(s\\)。这不必有网络规模进入效用——一个人换手机也疼。Klemperer 把「先争夺、后收租」写成两期价格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两期。一期无锁定，需求对价格很敏感，厂商用低价（甚至低于成本）买份额。二期老客户面对 \\(s\\)，剩余需求变陡，加价上升。理性消费者预见到二期被「敲」，一期愿意付的保留价格下降，于是一期竞争把二期租金提前打掉——在完全信息、无折现摩擦下，利润未必高于无转换成本的伯川德。缺口不是再写网络的 \\(n^e\\)，而是：<strong>\\(s\\) 怎样把弹性在时期之间挪动，以及「看起来很竞争」的入门价为什么仍可与事后势力共存。</strong></p><p>与网络对照：网络是别人也在才值钱；\\(s\\) 是我自己的沉淀，即使对手的网更大，搬家费仍在。二者常一起出现（数据、联系人），但比较静态不同：纯 \\(s\\) 不需要多重实现预期。</p><h3 id="入门补贴不是掠夺自动成立" tabindex="-1">入门补贴不是掠夺自动成立 <a class="header-anchor" href="#入门补贴不是掠夺自动成立" aria-label="Permalink to &quot;入门补贴不是掠夺自动成立&quot;">​</a></h3><p>一期低于成本可以是「买客户」，二期对同一批人回收，不必赶走对手。Ordover–Willig 的反事实仍可用：若对手一直在场，这笔入门价是否仍最优？转换成本模型里往往是的。不要把 Klemperer 的促销写成<a href="/econ/predatory-pricing">掠夺</a>。</p><p><span class="marginnote">Klemperer 1987：两期价格，老客户与新客户可被识别时，可以对新客折扣、对老客加价。不能识别时，统一价权衡「抢新」与「收老」。份额高的在位者更不愿降价抢新——这是惰性，不是共谋。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两期、逆向归纳。二期给定锁定存量，每家在老客市场上有 \\(s\\) 这么高的有效差异——有点像<a href="/econ/hotelling">霍特林</a>的 \\(t\\)，但 \\(t\\) 是横差异，\\(s\\) 是历史买过谁。一期厂商为二期存量竞争。折现因子、新客流入、能否识别新老，决定入门价有多低。</p><p>福利：二期加价造成无谓损失；一期过度促销可能浪费（广告、送机）。社会最优的 \\(s\\) 往往不是零——有些沉淀是学习真成本——但厂商有激励把 \\(s\\) 做大（不兼容、积分到期）。进入者必须从新客或买下 \\(s\\) 打起，在位者的存量本身就是壁垒。</p>',12)),(a(),n(d,null,{default:r(()=>[E(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLAT%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E4%B8%A4%E8%BE%B9%E4%BB%B7%E6%A0%BC%E7%BB%93%E6%9E%84%22%5D%20--%3E%20SW%5B%22%E7%94%A8%E6%88%B7%E6%B2%89%E6%B7%80%20s%22%5D%0A%20%20SW%20--%3E%20T1%5B%22%E4%B8%80%E6%9C%9F%EF%BC%9A%E6%8A%A2%E4%BB%BD%E9%A2%9D%EF%BC%8C%E4%BB%B7%E5%8F%AF%E5%BE%88%E4%BD%8E%22%5D%0A%20%20SW%20--%3E%20T2%5B%22%E4%BA%8C%E6%9C%9F%EF%BC%9A%E5%AF%B9%E8%80%81%E5%AE%A2%E5%8A%A0%E4%BB%B7%22%5D%0A%20%20T1%20--%3E%20CAP%5B%22%E4%BA%8B%E5%89%8D%E7%AB%9E%E4%BA%89%E6%B6%88%E8%80%97%E4%BA%8B%E5%90%8E%E7%A7%9F%E9%87%91%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>本课仍是产品市场。不要把 \\(s\\) 写成换做市商的队列位置；没有簿。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>弹性跨期挪动的机制是状态变量：买过之后，相对价格要相差超过 \\(s\\) 才换。二期交叉弹性下降，勒纳上升。一期把二期利润资本化进份额的边际收益，于是一期自己的勒纳下降，甚至为负。</p><p>不能识别新老时，降价会漏给老客，抢新的激励被卡住——在位者「温和」，进入者更凶。这与合谋的低价惩罚方向相反：这里的高价是锁定，不是卡特尔。</p><p>重叠的新客流把两期教具拉成稳态：每一期都有一批未锁定的人与一批老客。统一价是两群弹性的加权。市场份额高则老客权重大，降价更贵，于是大厂商更「安静」——观测上像合谋，一阶条件仍是锁定，不是惩罚路径。合约预告二期价，等于把 \\(s\\) 的敲竹杠提前写进一期，竞争回到可竞争式的打包。</p><p><span class="marginnote">Klemperer 1995 的综述把福利、进入、合谋（转换成本可帮助默契）收在一起。主干用 1987 的两期价格；合谋只作边界：锁定使惩罚偏离更疼，也可能使默契更容易。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>新客识别若被禁止，统一价下在位者更温和，进入者份额可以涨得更快。</p><p>合同里写清二期价，可以把敲竹杠提前抵消。消费者短视则一期竞争无法耗尽二期租金，利润上升、福利更差。厂商还有激励内生地做大 \\(s\\)：不兼容接口、积分过期、数据不可携。社会最优的学习成本不是零，但厂商选择的 \\(s\\) 通常偏高。下一课把 \\(s\\) 特化成耐用品加配套消耗品：打印机已经买了，墨盒是后市场。</p><p>后课默认：转换成本把竞争从二期挪到一期；事后加价与事前促销是同一租金的两面，不是自动掠夺。</p><p>本课不把入门低价自动写成掠夺。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(s\\) 是个人沉淀，不必有网络规模。</li><li>二期弹性下降、加价；一期为份额把租金提前打掉。</li><li>入门低于成本可以是买客户，要用反事实与掠夺分开。</li><li>下一课：耐用品把锁定写进配套后市场。</li><li>出处：Klemperer, <em>QJE</em>, 1987。</li></ul>',13))])}const T=o(c,[["render",B]]);export{C as __pageData,T as default};
